/**
 * The model actions built on {@code <set-null>} must clear the previous value, not keep it (the
 * generated {@code xNull()} setters once behaved as {@code unsetX()}).
 */
class ClearingActionsUnitTest {
  private static final OffsetDateTime LATER = OffsetDateTime.now().plusHours(1);

  @Test
  void testUnlockClearsTheBlock() {
    User blocked = User.builder()
        .uidValue(net.civeira.phylax.features.access.user.domain.valueobject.UidVO.from("user-1"))
        .tenantValue(TenantVO.from(TenantReference.of("tenant-1"))).nameValue(NameVO.from("alice"))
        .passwordValue(PasswordVO.fromPlain("x")).blockedUntilValue(BlockedUntilVO.from(LATER))
        .build();

    User unlocked = blocked.unlock();

    assertTrue(unlocked.getBlockedUntil().isEmpty());
  }

  @Test
  void testResetMfaTemporalCodeClearsThePendingSeed() {
    UserMfaEnrollment pending = UserMfaEnrollment.builder()
        .uidValue(net.civeira.phylax.features.access.usermfaenrollment.domain.valueobject.UidVO
            .from("enrollment-1"))
        .userValue(net.civeira.phylax.features.access.usermfaenrollment.domain.valueobject.UserVO
            .from(UserReference.of("user-1")))
        .pendingSeedValue(PendingSeedVO.fromPlain("seed"))
        .expiresAtValue(
            net.civeira.phylax.features.access.usermfaenrollment.domain.valueobject.ExpiresAtVO
                .from(LATER))
        .build();

    UserMfaEnrollment reset = pending.resetMfaTemporalCode();

    assertTrue(reset.getPendingSeedValue().getPendingSeedStored(null, "enrollment-1").isEmpty());
    assertTrue(reset.getExpiresAt().isEmpty());
  }

  @Test
  void testResetClearsTheVerificationCode() {
    UserVerificationCode pending = UserVerificationCode.builder()
        .uidValue(net.civeira.phylax.features.access.userverificationcode.domain.valueobject.UidVO
            .from("code-1"))
        .userValue(net.civeira.phylax.features.access.userverificationcode.domain.valueobject.UserVO
            .from(UserReference.of("user-1")))
        .purposeValue(PurposeVO.from(UserVerificationCodePurposeOptions.PASSWORD_RECOVERY))
        .codeHashValue(CodeHashVO.fromPlain("code")).returnUrlValue(ReturnUrlVO.from("https://x"))
        .expiresAtValue(ExpiresAtVO.from(LATER)).build();

    UserVerificationCode reset = pending.reset();

    assertTrue(reset.getCodeHashValue().getCodeHashStored(null).isEmpty());
    assertTrue(reset.getReturnUrl().isEmpty());
    assertTrue(reset.getExpiresAt().isEmpty());
  }
}
